(function(){
const B=window.EnergyOpsJointForecastData,dates=Object.keys(B.days).sort(),t=(z,e)=>interfaceLanguage==='en'?e:z,active=()=>!!S.jointForecast;
Object.assign(translations,{'模型预测结果 · 15分钟展示 / 小时调度':'Model forecasts ·15-minute display / hourly demo dispatch'});
const old={forecast,applyFilters,validDate,queryBar,rememberOutput,resetDemo,overview,reportText};
function get(){const d=B.days[S.date];if(!d||d.timestamps.length!==96||d.pv_kw.length!==96||d.load_kw.length!==96)throw Error('Invalid horizon');d.timestamps.forEach((v,i)=>{if(v!==`${S.date}T${String(Math.floor(i/4)).padStart(2,'0')}:${String(i%4*15).padStart(2,'0')}:00+08:00`||![d.pv_kw[i],d.load_kw[i]].every(n=>Number.isFinite(n)&&n>=0))throw Error('Invalid forecast');});return d;}
function apply(){const d=get(),hourly=window.EnergyOpsLoadForecast.hourly;data.pv=hourly(d.pv_kw);data.load=hourly(d.load_kw);data.actual=Array(24).fill(null);data.actualPV=Array(24).fill(null);delete data.loadForecast;data.jointForecast={issued_at:d.timestamps[0],pv_model:'GRU',load_model:'DormPatch-96',pv_kwp:20077.2,load_multiplier:100,...JSON.parse(JSON.stringify(d)),alignment:B.alignment};draft=Engine.plans(data,S);}
globalThis.setJointForecastDay=function(d){if(!dates.includes(d))return false;const changed=S.date!==d||!active();S.jointForecast=true;S.date=d;S.loadModel='demo';if(changed){invalidateOutputs();S.dataVersion++;data=Engine.dataset(S.scenario);}apply();render();return true;};
const priorKey=forecastInputKey;forecastInputKey=()=>JSON.stringify([priorKey(),active()?data.jointForecast:null]);
const priorLoad=setLoadForecastModel;globalThis.setLoadForecastModel=function(m){S.jointForecast=false;return priorLoad(m);};
validDate=d=>active()?dates.includes(d):old.validDate(d);
applyFilters=function(silent=false){if(!active())return old.applyFilters(silent);const d=$('#day')?.value||S.date;if(!dates.includes(d))return false;if(d!==S.date){invalidateOutputs();S.date=d;S.dataVersion++;data=Engine.dataset(S.scenario);}apply();if(!silent)render();return true;};
queryBar=function(extra='',run=false){if(!active())return old.queryBar(extra,run);return `<section class="card load-source-card"><div class="load-source-fields"><div class="field"><label>${t('联合预测日期','Paired forecast date')}</label><select id="joint-day" onchange="setJointForecastDay(this.value)">${dates.map(d=>`<option ${d===S.date?'selected':''}>${d}</option>`).join('')}</select></div><div><strong>GRU + DormPatch-96</strong><div>20,077.2 kWp · ${t('宿舍负荷×100','Dorm load ×100')} · 96 × 15 min</div></div></div></section>`;};
rememberOutput=function(kind){const r=old.rememberOutput(kind);if(active()&&kind==='forecast'){r.issuedAt=get().timestamps[0];r.version='GRU+DormPatch96-campus-v1';r.source='paired_trained_forecasts_cross_year';r.jointForecast={pv_kwp:20077.2,load_multiplier:100,alignment:B.alignment};}return r;};
function payload(){const d=get();return {forecast_origin:d.timestamps[0],timezone:'Asia/Shanghai',interval_minutes:15,power_unit:'kW',source:'historical_cross_year_replay',pv_kwp:20077.2,load_multiplier:100,steps:d.timestamps.map((timestamp,i)=>({step:i+1,timestamp,pv_power_kw:d.pv_kw[i],load_power_kw:d.load_kw[i]}))};}
globalThis.jointForecastPayload=()=>active()&&forecastReady()?payload():null;
globalThis.exportJointForecast=function(type='csv'){if(!active()||!forecastReady())return false;const p=payload();if(type==='json')download(`dispatch-${S.date}-96.json`,JSON.stringify(p,null,2),'application/json;charset=utf-8');else download(`dispatch-${S.date}-96.csv`,'\ufeffstep,timestamp,pv_power_kw,load_power_kw\r\n'+p.steps.map(r=>[r.step,r.timestamp,r.pv_power_kw,r.load_power_kw].join(',')).join('\r\n')+'\r\n','text/csv;charset=utf-8');return true;};
function chart(d){const L=65,ww=715,hh=225,max=Math.max(1,...d.pv_kw,...d.load_kw)*1.1,x=i=>L+i*ww/95,y=v=>15+hh*(1-v/max);let s='<svg viewBox="0 0 800 280" role="img" aria-label="PV and load 96-step power">';for(let j=0;j<=4;j++){const v=max*j/4;s+=`<line x1="65" x2="780" y1="${y(v)}" y2="${y(v)}" stroke="#edf0f5"/><text x="55" y="${y(v)+4}" text-anchor="end" font-size="11">${fmt(v,0)}</text>`;}for(let h=0;h<=24;h+=3)s+=`<text x="${L+h*ww/24}" y="265" text-anchor="middle" font-size="11">${h}:00</text>`;for(const [k,c] of [['pv_kw','#e7a023'],['load_kw','#1677ff']])s+=`<polyline fill="none" stroke="${c}" stroke-width="2.3" points="${d[k].map((v,i)=>`${x(i)},${y(v)}`).join(' ')}"/>`;return `<div class="legend"><span><i style="background:#e7a023"></i>${t('光伏 GRU','PV GRU')}</span><span><i style="background:#1677ff"></i>${t('负荷 DormPatch-96','Load DormPatch-96')}</span><span>kW</span></div><div class="chart">${s}</svg></div>`;}
forecast=function(){if(!active())return `<div class="note-line">${btn(t('切换校园联合预测','Campus paired forecasts'),`setJointForecastDay('${dates[0]}')`,'small')}</div>`+old.forecast();const ready=forecastReady(),d=get();let h=queryBar()+`<section class="card"><div class="cardhead"><h3>${t('光伏与负荷联合预测','PV & load paired forecasts')}</h3><div class="actions">${btn(t('输出预测数据','Generate forecast'),'outputForecast()','primary small')}${btn(t('导出调度CSV','Export dispatch CSV'),"exportJointForecast('csv')",'small',!ready)}${btn(t('导出JSON','Export JSON'),"exportJointForecast('json')",'small',!ready)}</div></div><div class="note-line">${t('归档预测回放｜光伏2023年与负荷2025年同月日配对，统一时间轴采用2025年。','Archived replay | PV2023 paired with load2025 by month/day; dispatch clock uses2025.')}</div>`;if(!ready)return h+outputEmpty('forecast')+'</section>';return h+`<div data-output-results="forecast">${chart(d)}<div class="kpis prediction-stats">${kpi(t('光伏预测电量','PV forecast energy'),fmt(d.pv_kw.reduce((a,b)=>a+b,0)*.25,1),'kWh','24 h')}${kpi(t('负荷预测电量','Load forecast energy'),fmt(d.load_kw.reduce((a,b)=>a+b,0)*.25,1),'kWh','24 h')}${kpi(t('预测步长','Forecast horizon'),'96','×15 min',t('两路功率均为kW','Both powers in kW'))}</div><div class="hour-table"><table><thead><tr><th>${t('时间','Time')}</th><th>${t('光伏功率','PV power')} (kW)</th><th>${t('负荷功率','Load power')} (kW)</th></tr></thead><tbody>${d.timestamps.map((v,i)=>`<tr><td>${v.slice(11,16)}</td><td>${fmt(d.pv_kw[i],2)}</td><td>${fmt(d.load_kw[i],2)}</td></tr>`).join('')}</tbody></table></div><div class="note-line">${t('输出供外部调度使用；储能4,000 kWh由调度端配置。负荷小时数据守恒重采样；权重不变，仅输出缩放。内部演示调度使用小时均值。','For external dispatch; configure4,000kWh downstream. Hourly load resampled preserving energy; fixed weights, scaled outputs. Internal demo uses hourly means.')}</div></div></section>`;};
overview=function(){return active()?old.overview().replace('模拟负荷 · 24个时段','模型负荷 · 24个时段').replace('校园负荷案例、光伏150 kWp和储能均为合成演示假设','光伏20,077.2 kWp、负荷×100联合预测回放；储能由外部调度端配置'):old.overview();};
reportText=function(r){const text=old.reportText(r);return r?.inputs?.data?.jointForecast?text.replace('全部数据为合成，预测与参考值非实测。','光伏与负荷使用归档模型预测，按容量缩放并跨年份配对。').replace('All default data are synthetic.','PV and load use archived trained forecasts with cross-year pairing.').replace('正式专业模型待接入。','预测结果已接入；外部调度待联调。')+'\nPaired GRU/DormPatch-96 archived forecasts; PV20077.2kWp; load100x;2023PV/2025load; hourly mean adapter; price/carbon/control remain demo.':text;};
resetDemo=function(){S.jointForecast=false;return old.resetDemo();};
if(!window.ENERGYOPS_DISABLE_JOINT_DEFAULT)setJointForecastDay(dates[0]);
})();
